/**
 * InputController - Pure input state tracker
 *
 * Tracks keyboard and gamepad input state without physics coupling.
 * Use getInput() to retrieve current input state.
 *
 * @class InputController
 * @short Pure input state tracker
 * @category Core
 * @tags Input, Keyboard
 */
export class InputController {
    /**
     * Create a new InputController.
     *
     * @param {Object} [options={}] - Configuration options
     * @param {EventTarget} [options.element] - Element to attach events to (virtualElement for offscreen, window for main thread)
     * @param {Object} [options.dispatcher] - Dispatcher with .on()/.off() for forwarded events (alternative to element)
     * @param {boolean} [options.enableEditorKeys=true] - Enable editor/debug keys (., ,, /)
     * @param {boolean} [options.enableCameraToggle=true] - Enable camera mode toggle (V key)
     * @param {Array} [options.keyConfig] - Custom key configuration (defaults to standard game controls)
     * @param {Function} [options.onToggleCamera] - Callback when camera toggle key is pressed
     * @param {Function} [options.onTogglePause] - Callback when pause key is pressed
     * @param {Function} [options.onToggleEditor] - Callback when editor toggle key is pressed
     * @param {Function} [options.onToggleOrbit] - Callback when orbit toggle key is pressed
     */
    constructor(options?: {
        element?: EventTarget;
        dispatcher?: any;
        enableEditorKeys?: boolean;
        enableCameraToggle?: boolean;
        keyConfig?: any[];
        onToggleCamera?: Function;
        onTogglePause?: Function;
        onToggleEditor?: Function;
        onToggleOrbit?: Function;
    });
    _element: EventTarget;
    _dispatcher: any;
    _enableEditorKeys: boolean;
    _enableCameraToggle: boolean;
    _disposed: boolean;
    _onToggleCamera: Function;
    _onTogglePause: Function;
    _onToggleEditor: Function;
    _onToggleOrbit: Function;
    _inputState: {
        forward: boolean;
        backward: boolean;
        left: boolean;
        right: boolean;
        jump: boolean;
    };
    _jumpPressed: boolean;
    _prevJumpState: boolean;
    _pressedKeys: Set<any>;
    _keyMap: {};
    _boundDownHandler: any;
    _boundUpHandler: any;
    _boundBlurHandler: any;
    /**
     * Build key map from configuration array.
     * @private
     */
    private _buildKeyMap;
    /**
     * Register all event listeners.
     * @private
     */
    private _registerListeners;
    /**
     * Handle keydown events.
     * @private
     */
    private _handleKeyDown;
    /**
     * Handle keyup events.
     * @private
     */
    private _handleKeyUp;
    /**
     * Handle toggle actions (camera, pause, editor, orbit).
     * @private
     */
    private _handleToggleAction;
    /**
     * Handle blur/contextmenu events - release all keys.
     * @private
     */
    private _handleBlur;
    /**
     * Release all pressed keys and reset input state.
     */
    releaseAllKeys(): void;
    /**
     * Check if a specific action key is currently pressed.
     * @param {string} action - Action name (forward, backward, left, right, jump)
     * @returns {boolean} Whether the action key is pressed
     */
    isPressed(action: string): boolean;
    /**
     * Get current movement input state.
     * @returns {{ forward: boolean, backward: boolean, left: boolean, right: boolean }}
     */
    getMovementState(): {
        forward: boolean;
        backward: boolean;
        left: boolean;
        right: boolean;
    };
    /**
     * Get current input state formatted for PhysicsController.applyInput().
     *
     * Jump uses edge detection - jumpPressed is only true on the frame
     * the key goes down, not while held. This prevents multiple physics
     * steps from seeing the same jump input.
     *
     * @returns {{ x: number, y: number, jump: boolean, jumpPressed: boolean }} Input state object
     *
     * @example
     * ```javascript
     * // In render loop (if not using PhysicsController's automatic input)
     * physicsController.applyInput(0, inputController.getInput());
     * ```
     */
    getInput(): {
        x: number;
        y: number;
        jump: boolean;
        jumpPressed: boolean;
    };
    /**
     * Get current movement input as a normalized vector.
     * @returns {{ x: number, y: number }} Normalized input vector
     * @deprecated Use getInput() instead
     */
    getMovementInput(): {
        x: number;
        y: number;
    };
    /**
     * Set input state programmatically (for gamepad or touch controls).
     *
     * @param {Object} state - Input state to set
     * @param {boolean} [state.forward] - Forward state
     * @param {boolean} [state.backward] - Backward state
     * @param {boolean} [state.left] - Left state
     * @param {boolean} [state.right] - Right state
     * @param {boolean} [state.jump] - Jump state
     */
    setInputState(state: {
        forward?: boolean;
        backward?: boolean;
        left?: boolean;
        right?: boolean;
        jump?: boolean;
    }): void;
    /**
     * Set input from analog values (for gamepad sticks).
     *
     * @param {number} x - X axis value (-1 to 1)
     * @param {number} y - Y axis value (-1 to 1)
     * @param {boolean} [jump=false] - Jump button state
     * @param {number} [deadzone=0.2] - Deadzone threshold
     */
    setAnalogInput(x: number, y: number, jump?: boolean, deadzone?: number): void;
    /**
     * Dispose and clean up all event listeners.
     * Call this when the controller is no longer needed.
     */
    dispose(): void;
}
export default InputController;
